<?php
namespace App\Http\Controllers\Auth; use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Validation\ValidationException;
class ConfirmablePasswordController extends Controller { public function show(){ return view('auth.confirm-password'); } public function store(Request $r){ if(!Auth::guard('web')->validate(['email'=>$r->user()->email,'password'=>$r->password])) throw ValidationException::withMessages(['password'=>'The provided password does not match our records.']); $r->session()->put('auth.password_confirmed_at',time()); return redirect()->intended(route('dashboard')); } }
